UPDATE stage_prompts
SET config = json_set(
  config,
  '$.items.story.content.autoPopulate.geminiResponseFields', json('[{"key": "characters", "shape": "array of {name, description} — one entry per distinct person; if multiple people appear together (a couple, a family, friends), give each their own separate entry (e.g. ''Husband'', ''Wife'') — never merge more than one person into a single entry like ''Couple''. description must describe ONLY this one person''s own fixed visual appearance (age, build, hair, skin tone, outfit, distinguishing features) as they''d look alone in a solo reference sheet — never mention any other person, any prop, or what they''re doing/using in a specific scene.", "createsItemsIn": {"stage": 3, "itemKey": "character"}}, {"key": "properties", "shape": "array of {name, description} — one entry per distinct physical object/prop. description must describe ONLY this object''s own fixed visual appearance (material, color, shape, size, condition, brand markings) as it would look alone on a plain background in a solo reference sheet — never mention any person, any other object, or what''s being done with it in a scene (e.g. write ''A tan leather three-seat sofa with rolled arms and wooden legs'', not ''a sofa where someone relaxes'').", "createsItemsIn": {"stage": 3, "itemKey": "property"}}, {"key": "backgrounds", "shape": "array of {name, description} — one entry per distinct location/setting. description must describe ONLY this location''s own fixed visual appearance (layout, furniture, lighting, colors) as an empty environment reference — never mention any person or action happening in it.", "createsItemsIn": {"stage": 3, "itemKey": "background"}}, {"key": "sounds", "shape": "array of {name, description} — one entry per distinct sound/music cue. description must describe ONLY this sound''s own qualities (type, mood, tempo/instrumentation if music) — never mention a specific scene''s action or which character is present when it plays.", "createsItemsIn": {"stage": 3, "itemKey": "sound"}}, {"key": "scenes", "shape": "array of {name, location, action, dialogue, emotion} — one entry per numbered beat in the storyboard; location and action are required for every scene; dialogue should be the exact line from the storyboard if this beat has one (same language, never translated), or omitted if this beat has no dialogue; emotion must be exactly one of: Frustrated, Curious, Relieved, Happy, Excited, Confident, Calm", "createsItemsIn": {"stage": 4, "itemKey": "scene"}}]')
)
WHERE stage = 2;
